"use client";

import { useState, useEffect } from "react";

export interface CookiePreferences {
  essential: boolean;
  analytics: boolean;
  marketing: boolean;
  functional: boolean;
}

export interface CookieConsentState {
  consentGiven: boolean; // Has the user made a choice?
  preferences: CookiePreferences;
}

const DEFAULT_PREFERENCES: CookiePreferences = {
  essential: true,
  analytics: false,
  marketing: false,
  functional: false,
};

export function useCookieConsent() {
  const [state, setState] = useState<CookieConsentState>({
    consentGiven: false,
    preferences: DEFAULT_PREFERENCES,
  });
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
    try {
      const stored = localStorage.getItem("cookie-consent-v2");
      if (stored) {
        setState(JSON.parse(stored));
      }
    } catch (e) {
      console.error("Failed to parse cookie consent", e);
    }
  }, []);

  const saveConsent = (preferences: CookiePreferences) => {
    const newState = {
      consentGiven: true,
      preferences: {
        ...preferences,
        essential: true, // Always forced
      },
    };
    setState(newState);
    localStorage.setItem("cookie-consent-v2", JSON.stringify(newState));
  };

  const acceptAll = () => {
    saveConsent({
      essential: true,
      analytics: true,
      marketing: true,
      functional: true,
    });
  };

  const rejectAll = () => {
    saveConsent({
      essential: true,
      analytics: false,
      marketing: false,
      functional: false,
    });
  };

  return {
    ...state,
    mounted,
    saveConsent,
    acceptAll,
    rejectAll,
  };
}

// Type for global dataLayer and Meta Pixel
declare global {
  interface Window {
    dataLayer: unknown[];
    fbq: (...args: unknown[]) => void;
  }
}

export const trackLeadEvent = (metadata?: { source: string }) => {
  if (typeof window !== "undefined" && typeof window.fbq === "function") {
    window.fbq("track", "Lead", metadata);
    console.log("Meta Pixel: 'Lead' event tracked successfully.", metadata);
  } else {
    console.warn("Meta Pixel: fbq is not defined or initialized yet.");
  }
};
